from flask import Flask, request
import os
app = Flask(__name__)
@app.get('/resource')
def resource():
    filename = request.args.get('file', 'notes.txt')
    base_dir = os.path.join(os.path.dirname(__file__), 'public')
    # REPAIR-PATCH: path normalisation + containment check (CWE-22 fix)
    filepath = os.path.realpath(os.path.join(base_dir, filename))
    real_base = os.path.realpath(base_dir)
    if not (filepath == real_base or filepath.startswith(real_base + os.sep)):
        return 'Access denied', 403
    try:
        with open(filepath, encoding='utf-8') as stream:
            return stream.read()
    except OSError:
        return 'missing', 404

