from flask import Flask, request, send_from_directory, abort
import os
app = Flask(__name__)

@app.get('/resource')
def resource():
    filename = request.args.get('file', 'notes.txt')
    base_dir = os.path.join(os.path.dirname(__file__), 'public')
    filepath = os.path.join(base_dir, filename)

    # Canonicalize and resolve the path
    canonical_path = os.path.realpath(filepath)
    if not os.path.commonpath([base_dir, canonical_path]) == base_dir:
        abort(403)

    try:
        return send_from_directory(base_dir, filename)
    except FileNotFoundError:
        abort(404)

